test('starts with initial selection', () => {
  const { result } = renderHook(() => useMultiSelect(['a']));
  expect(result.current.isSelected('a')).toBe(true);
});

test('toggle adds item if absent', () => {
  const { result } = renderHook(() => useMultiSelect([]));
  act(() => result.current.toggle('x'));
  expect(result.current.isSelected('x')).toBe(true);
});

test('toggle removes item if present', () => {
  const { result } = renderHook(() => useMultiSelect(['x']));
  act(() => result.current.toggle('x'));
  expect(result.current.isSelected('x')).toBe(false);
});

test('selectAll selects all given items', () => {
  const { result } = renderHook(() => useMultiSelect([]));
  act(() => result.current.selectAll(['a', 'b', 'c']));
  expect(result.current.isSelected('a')).toBe(true);
  expect(result.current.isSelected('c')).toBe(true);
});

// __hidden__
test('clear empties selection', () => {
  const { result } = renderHook(() => useMultiSelect(['a', 'b']));
  act(() => result.current.clear());
  expect(result.current.selected.size).toBe(0);
});

