import { useState } from 'react';

export function useMultiSelect(initial = []) {
  const [selected, setSelected] = useState(() => new Set(initial));
  return {
    selected,
    toggle: (item) => setSelected(s => { const n = new Set(s); n.has(item) ? n.delete(item) : n.add(item); return n; }),
    selectAll: (items) => setSelected(new Set(items)),
    clear: () => setSelected(new Set()),
    isSelected: (item) => selected.has(item),
  };
}
